import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, lineDiscount, bulkDiscount, lineVAT, invoiceTotals } from '../src/totals.js';

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 2, unitPrice: 1000 }), 2000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 500 }), 500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 100 }), 1000);
});

test('lineTotal with zero qty', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 1000 }), 0);
});

test('lineDiscount calculates percent of lineTotal', () => {
  assert.equal(lineDiscount({ qty: 100, unitPrice: 1000, discountPercent: 10 }), 10000);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 1000, discountPercent: 5 }), 5000);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 1000, discountPercent: 0 }), 0);
});

test('lineDiscount defaults to 0% if not specified', () => {
  assert.equal(lineDiscount({ qty: 100, unitPrice: 1000 }), 0);
});

test('lineDiscount is never negative', () => {
  assert.equal(lineDiscount({ qty: 100, unitPrice: 1000, discountPercent: -10 }), 0);
});

test('lineDiscount with fractional result', () => {
  assert.equal(lineDiscount({ qty: 100, unitPrice: 1000, discountPercent: 2.5 }), 2500);
  assert.equal(lineDiscount({ qty: 33, unitPrice: 100, discountPercent: 10 }), 330);
});

test('lineVAT calculates VAT on amount after discount', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const bulk = bulkDiscount(line);
  const discountedAmount = total - discount - bulk;
  const expectedVAT = Math.round(discountedAmount * 21 / 100);
  assert.equal(lineVAT(line), expectedVAT);
});

test('lineVAT with no discount', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21 };
  const total = lineTotal(line);
  const bulk = bulkDiscount(line);
  const expectedVAT = Math.round((total - bulk) * 21 / 100);
  assert.equal(lineVAT(line), expectedVAT);
});

test('lineVAT defaults to 0% if not specified', () => {
  assert.equal(lineVAT({ qty: 100, unitPrice: 1000 }), 0);
});

test('lineVAT with zero discount percent', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const bulk = bulkDiscount(line);
  const expectedVAT = Math.round((100000 - bulk) * 21 / 100);
  assert.equal(lineVAT(line), expectedVAT);
});

test('lineVAT with rounding', () => {
  assert.equal(lineVAT({ qty: 1, unitPrice: 100, vatRate: 21 }), 21);
  assert.equal(lineVAT({ qty: 1, unitPrice: 1, vatRate: 21 }), 0);
});

test('lineVAT never negative', () => {
  assert.equal(lineVAT({ qty: 100, unitPrice: 1000, discountPercent: 200, vatRate: 21 }), 0);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  const lineDisc = 1000;
  const bulk = 225;
  assert.equal(totals.discount, 1225);
  const vat = Math.round((10000 - 1000 - 225) * 21 / 100);
  assert.equal(totals.vat, vat);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 10000 - 1225 + vat);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000);
  const line1Disc = 1000;
  const line1Bulk = 225;
  const line2Disc = 500;
  const line2Bulk = 0;
  const totalDisc = line1Disc + line1Bulk + line2Disc + line2Bulk;
  assert.equal(totals.discount, totalDisc);
  const line1Vat = Math.round((10000 - 1000 - 225) * 21 / 100);
  const line2Vat = Math.round((10000 - 500) * 21 / 100);
  const totalVat = line1Vat + line2Vat;
  assert.equal(totals.vat, totalVat);
  assert.equal(totals.total, 20000 - totalDisc + totalVat);
});

test('invoiceTotals with no discount', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  const bulk = 2500;
  assert.equal(totals.discount, bulk);
  const vat = Math.round((100000 - bulk) * 21 / 100);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 100000 - bulk + vat);
});

test('invoiceTotals with voucher', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  const bulk = 2500;
  const vat = Math.round((100000 - bulk) * 21 / 100);
  assert.equal(totals.vat, vat);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 100000 - bulk + vat - 5000);
});

test('invoiceTotals with no voucher defaults to 0', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals total never negative', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 0 }],
    voucher: { code: 'BIG', amount: 200000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21 },
      { qty: 100, unitPrice: 1000, vatRate: 6 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 200000);
  const bulk1 = 2500;
  const bulk2 = 2500;
  const totalBulk = bulk1 + bulk2;
  assert.equal(totals.discount, totalBulk);
  const line1Vat = Math.round((100000 - 2500) * 21 / 100);
  const line2Vat = Math.round((100000 - 2500) * 6 / 100);
  const totalVat = line1Vat + line2Vat;
  assert.equal(totals.vat, totalVat);
  assert.equal(totals.total, 200000 - totalBulk + totalVat);
});

test('invoiceTotals with complex scenario', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 2000, discountPercent: 10, vatRate: 21 },
      { qty: 20, unitPrice: 500, discountPercent: 5, vatRate: 6 },
      { qty: 1, unitPrice: 50000, discountPercent: 0, vatRate: 21 },
    ],
    voucher: { code: 'SAVE', amount: 2000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 70000);
  const line1Disc = 1000;
  const line1Bulk = 0;
  const line2Disc = 500;
  const line2Bulk = 225;
  const line3Disc = 0;
  const line3Bulk = 0;
  const totalDisc = line1Disc + line1Bulk + line2Disc + line2Bulk + line3Disc + line3Bulk;
  assert.equal(totals.discount, totalDisc);
  const line1Vat = Math.round((10000 - 1000) * 21 / 100);
  const line2Vat = Math.round((10000 - 500 - 225) * 6 / 100);
  const line3Vat = Math.round(50000 * 21 / 100);
  const totalVat = line1Vat + line2Vat + line3Vat;
  assert.equal(totals.vat, totalVat);
  assert.equal(totals.voucher, 2000);
  assert.equal(totals.total, 70000 - totalDisc + totalVat - 2000);
});

test('invoiceTotals returns all properties', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(Object.keys(totals).length, 5);
  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('vat' in totals);
  assert.ok('voucher' in totals);
  assert.ok('total' in totals);
});

test('bulkDiscount returns 0 for qty < 10', () => {
  assert.equal(bulkDiscount({ qty: 1, unitPrice: 1000 }), 0);
  assert.equal(bulkDiscount({ qty: 5, unitPrice: 1000 }), 0);
  assert.equal(bulkDiscount({ qty: 9, unitPrice: 1000 }), 0);
});

test('bulkDiscount returns 2.5% of amount after line discount for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  const total = lineTotal(line);
  const lineDisc = lineDiscount(line);
  const afterFirstDiscount = total - lineDisc;
  const expected = Math.max(0, afterFirstDiscount * 2.5 / 100);
  assert.equal(bulkDiscount(line), expected);
});

test('bulkDiscount with exactly 10 units', () => {
  const line = { qty: 10, unitPrice: 1000 };
  const bulk = bulkDiscount(line);
  assert.equal(bulk, 250);
});

test('bulkDiscount with 11 units', () => {
  const line = { qty: 11, unitPrice: 1000 };
  const bulk = bulkDiscount(line);
  assert.equal(bulk, 275);
});

test('bulkDiscount applied after line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  const total = 10000;
  const lineDisc = 1000;
  const afterLineDisc = 9000;
  const expected = 225;
  assert.equal(bulkDiscount(line), expected);
});

test('bulkDiscount is never negative', () => {
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 1000, discountPercent: 200 }), 0);
});

test('bulkDiscount with no line discount', () => {
  const line = { qty: 10, unitPrice: 1000 };
  const total = 10000;
  const expected = 250;
  assert.equal(bulkDiscount(line), expected);
});

test('bulkDiscount with zero unitPrice', () => {
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 0 }), 0);
});

test('lineVAT accounts for bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const total = 10000;
  const lineDisc = 0;
  const bulk = 250;
  const afterAllDiscounts = 10000 - 0 - 250;
  const expected = Math.round(afterAllDiscounts * 21 / 100);
  assert.equal(lineVAT(line), expected);
});

test('lineVAT with bulk discount and line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const total = 10000;
  const lineDisc = 1000;
  const bulk = 225;
  const afterAllDiscounts = total - lineDisc - bulk;
  const expected = Math.round(afterAllDiscounts * 21 / 100);
  assert.equal(lineVAT(line), expected);
});

test('invoiceTotals includes bulk discount in total discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const expectedLineDisc = 1000;
  const expectedBulkDisc = 225;
  assert.equal(totals.discount, expectedLineDisc + expectedBulkDisc);
});

test('invoiceTotals with bulk discount on one line only', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 250);
  const line1Vat = Math.round((10000 - 250) * 21 / 100);
  const line2Vat = Math.round(5000 * 21 / 100);
  assert.equal(totals.vat, line1Vat + line2Vat);
});

test('invoiceTotals with bulk discount on multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 15, unitPrice: 500, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17500);
  const bulk1 = 250;
  const bulk2 = 187.5;
  const expectedDiscount = bulk1 + bulk2;
  assert.equal(totals.discount, expectedDiscount);
});

test('invoiceTotals with bulk discount and line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const total = 10000;
  const lineDisc = 1000;
  const bulk = 225;
  const afterDiscounts = total - lineDisc - bulk;
  const vat = Math.round(afterDiscounts * 21 / 100);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 10000 - 1225 + vat);
});

test('bulk discount threshold edge cases', () => {
  assert.equal(bulkDiscount({ qty: 9.99, unitPrice: 1000 }), 0);
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 1000 }), 250);
  assert.equal(bulkDiscount({ qty: 10.01, unitPrice: 1000 }), 250.25);
});

test('invoiceTotals with bulk discount and voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  const vat = Math.round(9750 * 21 / 100);
  assert.equal(totals.vat, vat);
  assert.equal(totals.voucher, 1000);
  assert.equal(totals.total, 10000 - 250 + vat - 1000);
});

